func statusSlug(s string) string {
	switch s {
	case "Exploring":
		return "exploring"
	case "Building":
		return "building"
	case "Validating":
		return "validating"
	case "Shipped":
		return "shipped"
	default:
		return "paused"
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	result := ""
	for n > 0 {
		result = string(rune('0'+n%10)) + result
		n /= 10
	}
	return result
}

func countByStatus(ideas []lab.Idea, status lab.Status) int {
	count := 0
	for _, i := range ideas {
		if i.Status == status {
			count++
		}
	}
	return count
}

